import numpy as np

def get_rank(n):
    num_pillars = 3 * n * n
    num_cubes = n**3
    matrix = np.zeros((num_cubes, num_pillars), dtype=int)

    # x-pillars: p_x[j, k] = {(i, j, k) | 0 <= i < n}
    for j in range(n):
        for k in range(n):
            p_idx = j * n + k
            for i in range(n):
                c_idx = i * n**2 + j * n + k
                matrix[c_idx, p_idx] = 1

    # y-pillars: p_y[i, k] = {(i, j, k) | 0 <= j < n}
    for i in range(n):
        for k in range(n):
            p_idx = n*n + i * n + k
            for j in range(n):
                c_idx = i * n**2 + j * n + k
                matrix[c_idx, p_idx] = 1

    # z-pillars: p_z[i, j] = {(i, j, k) | 0 <= k < n}
    for i in range(n):
        for j in range(n):
            p_idx = 2 * n*n + i * n + j
            for k in range(n):
                c_idx = i * n**2 + j * n + k
                matrix[c_idx, p_idx] = 1

    # We need rank over GF(2).
    # Let's use a simple Gaussian elimination for rank over GF(2).
    rank = 0
    m, p = matrix.shape
    mat = matrix.copy()
    for col in range(p):
        if rank == m:
            break
        # Find a row with 1 in this column
        pivot = -1
        for r in range(rank, m):
            if mat[r, col] == 1:
                pivot = r
                break
        if pivot != -1:
            mat[[rank, pivot]] = mat[[pivot, rank]]
            for r in range(m):
                if r != rank and mat[r, col] == 1:
                    mat[r] = (mat[r] + mat[rank]) % 2
            rank += 1
    return rank, num_pillars

