        if rank == m: break
        pivot = -1
        for r in range(rank, m):
            if mat[r, col] == 1:
                pivot = r
                break
        if pivot != -1:
            mat[[rank, pivot]] = mat[[pivot, rank]]
            for r in range(m):
                if r != rank and mat[r, col] == 1:
                    mat[r] = (mat[r] + mat[rank]) % 2
            pivot_rows.append(rank)
            pivot_cols.append(col)
            rank += 1

    null_space = []
    free_cols = [c for c in range(p) if c not in pivot_cols]
    for free_col in free_cols:
        v = np.zeros(p, dtype=int)
        v[free_col] = 1
